const W=params.width,D=params.depth,H=params.height;
const Hf=H*0.8,Hb=Math.max(0.45,H*0.3);
const main={preset:'fabric',color:params.color,roughness:0.95,doubleSided:true};
const band={preset:'fabric',color:params.stripe,roughness:0.9,doubleSided:true};
const wood={preset:'wood',color:'#6b4a2e',roughness:0.85};
const rope={preset:'fabric',color:'#b9a27a',roughness:0.9};
const nP=Math.max(2,Math.round(W/2.4)+1);
const px=[];for(let i=0;i<nP;i++)px.push(-W/2+0.25+(W-0.5)*i/(nP-1));
function sagX(x){let d=1e9;for(const p of px)d=Math.min(d,Math.abs(x-p));const half=(W-0.5)/(nP-1)/2;return 0.32*Math.sin(Math.PI*0.5*Math.min(1,d/half));}
function roofY(x,z){const t=z>=0?z/(D/2):-z/(D/2);const y=z>=0?H-(H-Hf)*t:H-(H-Hb)*t;const mid=Math.sin(Math.PI*Math.min(1,t));return y-sagX(x)*(0.45+0.55*(1-Math.abs(t-0.5)*2))-0.06*mid;}
const nb=Math.max(6,Math.round(D/0.42));const bl=D/nb;
let mm=null,bm=null;
for(let i=0;i<nb;i++){
 const z0=-D/2+i*bl;
 const p=api.plane(W+0.3,bl,Math.round(W*3),2).translate(0,0,z0+bl/2);
 p.warp(function(x,y,z){return [x,roofY(x,z),z];});
 const st=(i%3===1);
 if(st){bm=bm?bm.merge(p):p;}else{mm=mm?mm.merge(p):p;}
}
api.add(mm,main);if(bm)api.add(bm,band);
// back curtain and the side curtains of the back half (front stays open)
const back=api.plane(W+0.3,Hb+0.02,Math.round(W*2),1).rotate(90,0,0).translate(0,(Hb+0.02)/2,-D/2);
back.warp(function(x,y,z){return [x,y,z-0.06*Math.sin(Math.PI*((x+W/2)/(W/(nP-1))))];});
api.add(back,main);
for(const s of [-1,1]){
 const prof=[[D/2,0],[D/2,Hb],[0,H-0.04],[-D*0.12,Hf+(H-Hf)*0.75],[-D*0.12,0]];
 const side=api.extrude(prof,0.03).rotate(0,90,0).translate(s*(W/2+0.13),0,0);
 api.add(side,main);
 // a light band along the side curtain hem
 api.add(api.box(0.035,0.12,D*0.62).translate(s*(W/2+0.14),0.35,-D*0.19),band);
}
// poles: the ridge row, the raised front row and short back poles
for(const x of px){
 api.add(api.cylinder(0.045,0.055,H-0.05,6).translate(x,(H-0.05)/2,0),wood);
 api.add(api.cylinder(0.04,0.05,Hf-0.04,6).translate(x,(Hf-0.04)/2,D/2),wood);
 api.add(api.cylinder(0.035,0.04,Hb,6).translate(x,Hb/2,-D/2),wood);
 // guy ropes from the front and back eaves to stakes
 api.add(api.tube([[x,Hf-0.05,D/2],[x,0.03,D/2+1.3]],0.012,4),rope);
 api.add(api.tube([[x,Hb-0.02,-D/2],[x,0.03,-D/2-1.0]],0.012,4),rope);
 api.add(api.box(0.05,0.18,0.05).translate(x,0.09,D/2+1.3),wood);
 api.add(api.box(0.05,0.18,0.05).translate(x,0.09,-D/2-1.0),wood);
}
for(const s of [-1,1]){
 api.add(api.tube([[s*(W/2+0.1),H*0.7,0],[s*(W/2+1.1),0.03,0]],0.012,4),rope);
 api.add(api.box(0.05,0.18,0.05).translate(s*(W/2+1.1),0.09,0),wood);
}
// rug and cushions under the open front
const rugM={preset:'fabric',color:params.rug,roughness:0.95};
api.add(api.box(W*0.72,0.025,D*0.72).translate(0,0.012,0.05),rugM);
api.add(api.box(W*0.6,0.03,D*0.56).translate(0,0.02,0.05),{preset:'fabric',color:api.mix(params.rug,'#e0b060',0.45),roughness:0.95});
const cush={preset:'fabric',color:api.mix(params.rug,'#2a4a6a',0.55),roughness:0.95};
for(let i=0;i<Math.max(2,nP);i++){const x=-W*0.3+W*0.6*i/Math.max(1,nP-1);api.add(api.roundedBox(0.7,0.28,0.45,0.1).translate(x,0.16,-D/2+0.5),cush);}
api.add(api.cylinder(0.16,0.1,0.3,10).translate(W*0.22,0.15,D*0.18),{finish:'brass',color:'#a87a3a',metalness:0.8,roughness:0.45});
// colliders: poles and the closed back; the open front stays walkable
for(const x of px){api.collider({kind:'cylinder',halfHeight:H/2,radius:0.06,offset:[x,H/2,0]});api.collider({kind:'cylinder',halfHeight:Hf/2,radius:0.06,offset:[x,Hf/2,D/2]});}
api.collider({kind:'box',halfExtents:[W/2,Hb/2+0.1,0.1],offset:[0,Hb/2+0.1,-D/2]});
for(const s of [-1,1])api.collider({kind:'box',halfExtents:[0.05,H*0.35,D*0.31],offset:[s*(W/2+0.13),H*0.35,-D*0.19]});
return api.build();

