const leg=function(x,z,front){
 const out=[];
 if(front){
  out.push({shape:'capsule',a:[x,1.5,z],b:[x+0.03,1.02,z],r:0.105});
  out.push({shape:'capsule',a:[x+0.03,1.02,z],b:[x+0.04,0.64,z],r:0.068});
  out.push({shape:'ellipsoid',r:[0.07,0.075,0.068],at:[x+0.05,0.62,z]});
  out.push({shape:'capsule',a:[x+0.04,0.6,z],b:[x+0.06,0.13,z],r:0.046});
  out.push({shape:'ellipsoid',r:[0.12,0.055,0.09],at:[x+0.1,0.055,z]});
 } else {
  out.push({shape:'capsule',a:[x,1.52,z],b:[x+0.13,1.05,z],r:0.13});
  out.push({shape:'capsule',a:[x+0.13,1.05,z],b:[x-0.06,0.62,z],r:0.07});
  out.push({shape:'ellipsoid',r:[0.075,0.07,0.06],at:[x-0.06,0.62,z]});
  out.push({shape:'capsule',a:[x-0.06,0.6,z],b:[x-0.02,0.13,z],r:0.045});
  out.push({shape:'ellipsoid',r:[0.12,0.055,0.09],at:[x+0.02,0.055,z]});
 }
 return out;
};
const body=[
 {shape:'ellipsoid',r:[0.74,0.4,0.33],at:[0,1.62,0]},
 {shape:'ellipsoid',r:[0.58,0.3,0.3],at:[0.05,1.48,0]},
 {shape:'ellipsoid',r:[0.4,0.36,0.25],at:[-0.04,1.98,0]},
 {shape:'ellipsoid',r:[0.24,0.2,0.2],at:[-0.04,2.2,0]},
 {shape:'ellipsoid',r:[0.3,0.36,0.27],at:[0.6,1.6,0]},
 {shape:'ellipsoid',r:[0.32,0.34,0.29],at:[-0.6,1.66,0]},
 {shape:'capsule',a:[0.72,1.72,0],b:[1.02,1.5,0],r:0.17},
 {shape:'capsule',a:[1.02,1.5,0],b:[1.27,1.56,0],r:0.13},
 {shape:'capsule',a:[1.27,1.56,0],b:[1.41,1.86,0],r:0.11},
 {shape:'capsule',a:[1.41,1.86,0],b:[1.45,2.1,0],r:0.1},
 {shape:'ellipsoid',r:[0.16,0.12,0.11],at:[1.48,2.15,0]},
 {shape:'capsule',a:[1.52,2.13,0],b:[1.8,2.04,0],r:0.085},
 {shape:'ellipsoid',r:[0.1,0.075,0.08],at:[1.82,2.02,0]},
 {shape:'capsule',a:[1.44,2.25,0.07],b:[1.4,2.33,0.11],r:0.025},
 {shape:'capsule',a:[1.44,2.25,-0.07],b:[1.4,2.33,-0.11],r:0.025},
 {shape:'capsule',a:[-0.88,1.82,0],b:[-0.95,1.25,0],r:0.035}
];
const items=body.concat(leg(0.5,0.16,true),leg(0.5,-0.16,true),leg(-0.58,0.17,false),leg(-0.58,-0.17,false));
const m=api.sdf({op:'union',k:0.07,items:items},{resolution:110,smooth:2});
api.add(m,{finish:'fabric',color:params.color,roughness:0.97});
api.add(api.sdf({shape:'ellipsoid',r:[0.05,0.1,0.05],at:[0,0,0]},{resolution:16}).translate(-0.96,1.2,0),{finish:'fabric',color:api.mix(params.color,'#3a2a1a',0.55),roughness:1});
const bag={finish:'fabric',color:params.bagColor,roughness:0.95};
const blanket={finish:'fabric',color:api.mix(params.bagColor,'#e8c070',0.35),roughness:0.95};
const pad=api.plane(0.5,0.9,6,10).warp(function(x,y,z){return [x+0.62,1.99-1.6*z*z,z];});
api.add(pad,{finish:'fabric',color:api.mix(params.bagColor,'#e8c070',0.35),roughness:0.95,doubleSided:true});
api.add(api.box(0.5,0.05,0.04).translate(0.62,2.0,0),bag);
for(const s of [-1,1]){
 api.add(api.roundedBox(0.42,0.36,0.13,0.05).translate(0.62,1.52,s*0.39),bag);
 api.add(api.box(0.44,0.05,0.14).translate(0.62,1.66,s*0.4),blanket);
}
api.collider({kind:'box',halfExtents:[0.95,1.05,0.36],offset:[0.3,1.1,0]});
return api.build();

cart.source:
const L = params.length;
const bedW = L * 0.42;
const bedLen = L * 0.56;
const plankT = L * 0.035;
const bedY = L * 0.41;
const bedZ = -L * 0.16;
const wheelR = L * 0.18;
const wheelX = bedW * 0.57;
const wheelY = wheelR;
const wheelZ = -L * 0.2;
const darkWood = api.mix(params.woodColor, '#2b180d', 0.32);
const lightWood = api.mix(params.woodColor, '#d5a665', 0.2);
const wood = { preset: 'wood', color: params.woodColor, roughness: 0.82 };
const woodDark = { preset: 'wood', color: darkWood, roughness: 0.88 };
const woodLight = { preset: 'wood', color: lightWood, roughness: 0.78 };
const iron = { preset: 'metal', color: '#343638', metalness: 0.8, roughness: 0.38 };
const ironDark = { preset: 'metal', color: '#202224', metalness: 0.72, roughness: 0.48 };
const plankCount = 7;
const plankW = bedW / plankCount * 0.91;
for (let i = 0; i < plankCount; i++) {
  const x = -bedW / 2 + (i + 0.5) * bedW / plankCount;
  const p = api.box(plankW, plankT, bedLen).translate(x, bedY, bedZ);
  p.vertexColor((vx, vy, vz) => api.mix(params.woodColor, lightWood, 0.18 + 0.12 * api.noise2(vz * 13 / L, vx * 8 / L)));
  api.add(p, { preset: 'wood', roughness: 0.82 });
}
const crossZ = [-L * 0.405, -L * 0.15, L * 0.105];
for (let i = 0; i < crossZ.length; i++) api.add(api.box(bedW * 1.04, L * 0.045, L * 0.055).translate(0, bedY - plankT, crossZ[i]), woodDark);
const railH = L * 0.18;
const postT = L * 0.035;
for (let side = -1; side <= 1; side += 2) {
  const x = side * bedW * 0.49;
  for (let j = 0; j < 4; j++) {
    const z = bedZ - bedLen * 0.45 + j * bedLen * 0.3;
    api.add(api.box(postT, railH, postT).translate(x, bedY + railH * 0.48, z), woodDark);
  }
  api.add(api.box(postT, postT, bedLen * 0.94).translate(x, bedY + railH * 0.92, bedZ), wood);
  api.add(api.box(postT * 0.75, postT * 0.75, bedLen * 0.94).translate(x, bedY + railH * 0.48, bedZ), woodLight);
}
const backZ = bedZ - bedLen * 0.5;
for (let j = 0; j < 4; j++) {
  const x = -bedW * 0.45 + j * bedW * 0.3;
  api.add(api.box(postT, railH, postT).translate(x, bedY + railH * 0.48, backZ), woodDark);
}
api.add(api.box(bedW, postT, postT).translate(0, bedY + railH * 0.92, backZ), wood);
api.add(api.cylinder(L * 0.025, L * 0.025, bedW * 1.28, 12).rotate(0, 0, 90).translate(0, wheelY, wheelZ), ironDark);
for (let side = -1; side <= 1; side += 2) {
  const x = side * wheelX;
  api.add(api.torus(wheelR, L * 0.018).rotate(0, 90, 0).translate(x, wheelY, wheelZ), iron);
  api.add(api.torus(wheelR * 0.84, L * 0.022).rotate(0, 90, 0).translate(x, wheelY, wheelZ), woodDark);
  api.add(api.cylinder(L * 0.048, L * 0.048, L * 0.09, 12).rotate(0, 0, 90).translate(x, wheelY, wheelZ), ironDark);
  for (let s = 0; s < 10; s++) {
    const a = s * 36;
    const ar = a * Math.PI / 180;
    const sy = wheelY + Math.cos(ar) * wheelR * 0.43;
    const sz = wheelZ + Math.sin(ar) * wheelR * 0.43;
    api.add(api.cylinder(L * 0.009, L * 0.012, wheelR * 0.76, 6).rotate(a, 0, 0).translate(x, sy, sz), woodLight);
  }
  api.add(api.cylinder(L * 0.028, L * 0.038, L * 0.115, 10).rotate(0, 0, 90).translate(side * (wheelX + L * 0.045), wheelY, wheelZ), iron);
}
const frontZ = bedZ + bedLen * 0.48;
for (let side = -1; side <= 1; side += 2) {
  const x = side * bedW * 0.4;
  const path = [[x, bedY - L * 0.035, frontZ - L * 0.04], [x, bedY - L * 0.055, L * 0.31], [side * bedW * 0.34, bedY - L * 0.13, L * 0.5]];
  api.add(api.tube(path, L * 0.025, 8), woodDark);
  api.add(api.cylinder(L * 0.032, L * 0.032, L * 0.15, 10).rotate(90, 0, 0).translate(side * bedW * 0.34, bedY - L * 0.13, L * 0.545), wood);
  api.add(api.torus(L * 0.035, L * 0.009).rotate(90, 0, 0).translate(side * bedW * 0.34, bedY - L * 0.13, L * 0.62), iron);
}
api.add(api.box(bedW * 0.68, L * 0.055, L * 0.12).translate(0, bedY - L * 0.09, frontZ - L * 0.02), woodDark);
api.collider({ kind: 'box', halfExtents: [bedW * 0.52, L * 0.12, bedLen * 0.5], offset: [0, bedY + L * 0.07, bedZ] });
api.collider({ kind: 'box', halfExtents: [bedW * 0.62, wheelR, L * 0.045], offset: [0, wheelY, wheelZ] });
api.collider({ kind: 'box', halfExtents: [bedW * 0.44, L * 0.04, L * 0.3], offset: [0, bedY - L * 0.08, L * 0.31] });
return api.build();

castle-gate.source:
const H = params.height;
const S = H / 8;
const towerR = 1.45 * S;
const towerH = 6.9 * S;
const towerX = 3.05 * S;
const wallD = 1.9 * S;
const gateHalf = 1.15 * S;
const springY = 2.7 * S;
const archR = gateHalf;
const crownY = springY + archR;
const stone = { preset: 'stone', color: params.stoneColor, roughness: 0.92, flatShading: true };
const darkStone = { preset: 'stone', color: api.mix(params.stoneColor, '#282826', 0.32), roughness: 0.95, flatShading: true };
const iron = { preset: 'metal', color: '#25282a', metalness: 0.72, roughness: 0.42 };
const wood = { preset: 'wood', color: '#4b3120', roughness: 0.88 };
const addStone = (mesh) => {
  mesh.vertexColor((x, y, z) => api.mix(params.stoneColor, '#5d594f', 0.10 + 0.10 * (api.noise3(x * 1.7, y * 1.7, z * 1.7) + 1) * 0.5));
  api.add(mesh, stone);
};
addStone(api.cylinder(towerR * 0.96, towerR, towerH, 16).translate(-towerX, towerH / 2, 0));
addStone(api.cylinder(towerR * 0.96, towerR, towerH, 16).translate(towerX, towerH / 2, 0));
addStone(api.box(towerX * 2, springY, wallD).translate(0, springY / 2, 0));
addStone(api.box(towerX * 2, 1.7 * S, wallD).translate(0, crownY + 0.85 * S, 0));
addStone(api.box(towerX - gateHalf, crownY - springY, wallD).translate(-(towerX + gateHalf) / 2, (springY + crownY) / 2, 0));
addStone(api.box(towerX - gateHalf, crownY - springY, wallD).translate((towerX + gateHalf) / 2, (springY + crownY) / 2, 0));
const archOuter = archR + 0.38 * S;
const archSegs = 11;
for (let side = -1; side <= 1; side += 2) {
  const z = side * (wallD / 2 + 0.035 * S);
  for (let i = 0; i < archSegs; i++) {
    const a0 = i * Math.PI / archSegs;
    const a1 = (i + 1) * Math.PI / archSegs;
    const shape = [
      [Math.cos(a0) * archR, springY + Math.sin(a0) * archR],
      [Math.cos(a0) * archOuter, springY + Math.sin(a0) * archOuter],
      [Math.cos(a1) * archOuter, springY + Math.sin(a1) * archOuter],
      [Math.cos(a1) * archR, springY + Math.sin(a1) * archR]
    ];
    const voussoir = api.extrude(shape, 0.15 * S).translate(0, 0, z);
    voussoir.vertexColor(() => i % 2 === 0 ? api.mix(params.stoneColor, '#d3c9ae', 0.18) : api.mix(params.stoneColor, '#504c45', 0.12));
    api.add(voussoir, stone);
  }
}
for (let side = -1; side <= 1; side += 2) {
  addStone(api.box(0.34 * S, springY, 0.16 * S).translate(side * (gateHalf + 0.19 * S), springY / 2, wallD / 2 + 0.04 * S));
  addStone(api.box(0.34 * S, springY, 0.16 * S).translate(side * (gateHalf + 0.19 * S), springY / 2, -wallD / 2 - 0.04 * S));
}
const gateZ = wallD / 2 + 0.14 * S;
for (let i = -3; i <= 3; i++) {
  const x = i * gateHalf * 0.285;
  const top = springY + Math.sqrt(Math.max(0, archR * archR - x * x)) - 0.13 * S;
  const bottom = 0.28 * S;
  api.add(api.box(0.075 * S, top - bottom, 0.09 * S).translate(x, (top + bottom) / 2, gateZ), iron);
  api.add(api.cone(0.095 * S, 0.32 * S, 6).rotate(180, 0, 0).translate(x, bottom, gateZ), iron);
}
for (let j = 0; j < 3; j++) {
  api.add(api.box(gateHalf * 1.9, 0.085 * S, 0.11 * S).translate(0, (0.9 + j * 0.72) * S, gateZ + 0.01 * S), iron);
}
const walkY = 5.82 * S;
addStone(api.box(towerX * 2.1, 0.25 * S, wallD * 1.25).translate(0, walkY, 0));
for (let side = -1; side <= 1; side += 2) {
  const z = side * wallD * 0.69;
  addStone(api.box(towerX * 2.15, 0.34 * S, 0.24 * S).translate(0, walkY + 0.29 * S, z));
  for (let i = -4; i <= 4; i++) {
    addStone(api.box(0.45 * S, 0.58 * S, 0.34 * S).translate(i * 0.72 * S, walkY + 0.72 * S, z));
  }
}
for (let t = -1; t <= 1; t += 2) {
  addStone(api.cylinder(towerR * 1.08, towerR * 1.08, 0.25 * S, 16).translate(t * towerX, towerH + 0.02 * S, 0));
  for (let i = 0; i < 12; i++) {
    const a = i * Math.PI * 2 / 12;
    const rr = towerR * 0.96;
    addStone(api.box(0.48 * S, 0.62 * S, 0.48 * S).rotate(0, -a * 180 / Math.PI, 0).translate(t * towerX + Math.cos(a) * rr, towerH + 0.43 * S, Math.sin(a) * rr));
  }
}
for (let t = -1; t <= 1; t += 2) {
  for (let side = -1; side <= 1; side += 2) {
    api.add(api.box(0.16 * S, 0.72 * S, 0.06 * S).translate(t * towerX, 3.55 * S, side * (towerR + 0.015 * S)), darkStone);
    api.add(api.box(0.42 * S, 0.12 * S, 0.065 * S).translate(t * towerX, 3.55 * S, side * (towerR + 0.025 * S)), darkStone);
  }
}
const rearZ = -wallD / 2 - 0.09 * S;
for (let side = -1; side <= 1; side += 2) {
  api.add(api.box(0.48 * S, 1.05 * S, 0.11 * S).translate(side * 1.72 * S, 1.05 * S, rearZ), wood);
  api.add(api.box(0.07 * S, 1.08 * S, 0.13 * S).translate(side * 1.72 * S, 1.05 * S, rearZ - 0.02 * S), iron);
}
api.add(api.box(0.72 * S, 0.42 * S, 0.09 * S).translate(0, 5.12 * S, wallD / 2 + 0.07 * S), darkStone);
api.collider({ kind: 'cylinder', radius: towerR, halfHeight: towerH / 2, offset: [-towerX, towerH / 2, 0] });
api.collider({ kind: 'cylinder', radius: towerR, halfHeight: towerH / 2, offset: [towerX, towerH / 2, 0] });
api.collider({ kind: 'box', halfExtents: [(towerX - gateHalf) / 2, springY / 2, wallD / 2], offset: [-(towerX + gateHalf) / 2, springY / 2, 0] });
api.collider({ kind: 'box', halfExtents: [(towerX - gateHalf) / 2, springY / 2, wallD / 2], offset: [(towerX + gateHalf) / 2, springY / 2, 0] });
api.collider({ kind: 'box', halfExtents: [towerX, 0.85 * S, wallD / 2], offset: [0, crownY + 0.85 * S, 0] });
return api.build();

desert-house.source:
const w=params.width,d=params.depth,f=Math.max(1,Math.round(params.floors));
const fh=3.0;
const wall={preset:'stone',finish:'plaster',color:params.color,roughness:0.95,surface:{layers:[{kind:'tone',amount:0.4},{kind:'grime',amount:0.35},{kind:'streaks',amount:0.3},{kind:'edgeWear',amount:0.4}]}};
const dark={color:'#2a1e16',roughness:0.9};
const wood={preset:'wood',color:params.trim};
const gold={preset:'gold'};
const H=f*fh;
api.add(api.box(w,H,d).translate(0,H/2,0),wall);
const pt=0.2,ph=0.6;
api.add(api.box(w,ph,pt).translate(0,H+ph/2,d/2-pt/2),wall);
