const S=360,N=240;
const probe=api.heightfield(2,2,10,10,function(){return 0;}).bounds();
const off=probe.min[0]>-1?S/2:0;
function ss(a,b,x){let t=(x-a)/(b-a);t=t<0?0:(t>1?1:t);return t*t*(3-2*t);}
const LX=50,LZ=-4;
const R=[[0,4],[-0.5,12],[-2.5,19],[-6.5,25],[-10.5,29],[-14,31.5]];
const RL=[0];for(let i=1;i<R.length;i++)RL.push(RL[i-1]+Math.hypot(R[i][0]-R[i-1][0],R[i][1]-R[i-1][1]));
const RT=RL[RL.length-1];
function road(X,Z){let best=1e9,s=0;for(let i=1;i<R.length;i++){const ax=R[i-1][0],az=R[i-1][1],bx=R[i][0],bz=R[i][1];const dx=bx-ax,dz=bz-az;let t=((X-ax)*dx+(Z-az)*dz)/(dx*dx+dz*dz);t=t<0?0:(t>1?1:t);const px=ax+dx*t,pz=az+dz*t;const d=Math.hypot(X-px,Z-pz);if(d<best){best=d;s=RL[i-1]+t*(RL[i]-RL[i-1]);}}return [best,s];}
function H(X,Z){
 const dp=Math.hypot(X,Z+25);
 const sth=Math.max(0,(Z+25)/Math.max(1,dp));
 let h=8*(1-ss(33,46+10*sth*sth,dp));
 h+=ss(34,38,dp)*(1-ss(44,48,dp))*0.4*api.noise2(X*0.15,Z*0.15);
 const az=Math.abs(Z+78);
 let ridge=14*(1-ss(4,24,az))*(1-ss(45,75,Math.abs(X)));
 ridge+=ss(5,10,az)*(ridge/14)*1.2*api.noise2(X*0.08,Z*0.08);
 h=Math.max(h,ridge);
 let w=ss(55,90,Math.hypot(X-5,Z+5));
 if(Z<-8&&Z>-82) w*=ss(4,10,Math.abs(X-LX));
 w*=1-ss(0.5,4,ridge);
 h+=w*(2.5*(0.5+0.5*api.fbm2(X*0.018,Z*0.032,3)));
 const r0=Math.hypot(X,Z);
 h+=ss(110,175,r0)*22*(0.55+0.45*api.fbm2(X*0.012+3,Z*0.012,4));
 const rd=road(X,Z);
 if(rd[0]<9){ const u=rd[1]/RT; const hr=8*(1-ss(0.02,1,u)); const m=1-ss(2.6,8,rd[0]); h=h*(1-m)+hr*m; }
 const dl=Math.hypot(X-LX,Z-LZ);
 if(dl<19){ h=h*ss(12,19,dl)-2*(1-ss(0,13.5,dl)); }
 return h;
}
const hf=api.heightfield(N,N,S,S,function(x,z){return H(x-off,z-off);});
hf.vertexColor(function(x,y,z){
 const X=x-off,Z=z-off; const n=0.5+0.5*api.noise2(X*0.21,Z*0.21);
 const dl=Math.hypot(X-LX,Z-LZ);
 let c=api.mix('#d6ab72','#e8c48c',n);
 if(y>9.5) c=api.mix(c,'#b98e5e',0.45);
 const dp=Math.hypot(X,Z+25);
 if(dp<33) c=api.mix('#c9a571','#d8b885',n);
 if(dp>31&&dp<47&&y>0.6&&y<7.6) c=api.mix(c,'#b8875a',0.35*(1-Math.abs(y-4)/4));
 if(dl<21.5){ const g=1-ss(16.5,21.5,dl); c=api.mix(c,api.mix('#5f7230','#8c9a48',n),g);}
 const rd=road(X,Z);
 if(rd[0]<3.6){ const g=1-ss(2.2,3.6,rd[0]); const n2=0.5+0.5*api.noise2(X*0.9,Z*0.9); c=api.mix(c,api.mix('#6e5a46','#86705a',n2),g);}
 if(y<-0.45) c=api.mix('#6f5e40','#86744f',n);
 return c;});
api.add(hf,{preset:'sand',color:'#ffffff',roughness:0.95});
// the packed-earth road from the caravan camp up to the main gate: a fine strip laid on the ramp (hidden under the sand off the road)
const RX0=-19,RX1=5,RZ0=1,RZ1=36,cx=(RX0+RX1)/2,cz=(RZ0+RZ1)/2;
function RY(X,Z){const rd=road(X,Z);if(rd[0]>2.75)return H(X,Z)-0.45;const u=rd[1]/RT;const hr=8*(1-ss(0.02,1,u));return hr+0.07-(rd[0]>2.3?0.5*(rd[0]-2.3)/0.45:0);}
const rm=api.heightfield(Math.round((RX1-RX0)/0.45),Math.round((RZ1-RZ0)/0.45),RX1-RX0,RZ1-RZ0,function(x,z){return RY(cx+x,cz+z);}).translate(cx,0,cz);
rm.vertexColor(function(x,y,z){const n=0.5+0.5*api.noise2(x*0.7,z*0.7);const rd=road(x,z);let c=api.mix('#9c7a56','#b48f68',n);if(Math.abs(rd[0]-1.0)<0.35)c=api.mix(c,'#7e6248',0.45);if(rd[0]>1.9)c=api.mix(c,'#c49a6a',0.5);return c;});
api.add(rm,{finish:'soil',color:'#ffffff',roughness:1});
api.autoColliders('trimesh');
return api.build();
